  double[]walk=Bodycam26.offset(0,1,.18,false,false,0,0),sprint=Bodycam26.offset(0,1,.18,true,false,0,0),aim=Bodycam26.offset(0,1,.18,true,true,0,0);ok(Math.abs(sprint[0])>Math.abs(walk[0])&&Math.abs(aim[0])<Math.abs(walk[0]),"sprint stronger and weapon aiming reduces bodycam");
